        name = m.group(1)
        if 'FAMILY' in name or name == 'TREE GENERATOR':
            continue
        persons.append((i, m.start(), m.end(), name))

unique = {}
for row, start, end, name in persons:
    if name not in unique:
        unique[name] = (row, start, end)

# For each node, find parent by scanning upward for nearest connector that leads to another node
# Look for vertical line above: in the row above, look around the horizontal span of the name
# Or more generally, trace upward following | and junctions

def getch(r, c):
    if 0 <= r < len(lines):
        line = lines[r]
        if 0 <= c < len(line):
            return line[c]
    return ' '

# Try a simple heuristic: parent is the closest name above with horizontal position closest to this name's center
edges = []
for name, (r, s, e) in unique.items():
    center = (s + e) // 2
    # look upward
    best = None
    best_dist = float('inf')
    for other, (orow, os, oe) in unique.items():
        if other == name:
            continue
        if orow < r:  # above
            oc = (os + oe) // 2
            dist = abs(oc - center) + (r - orow)  # prefer closer vertically and horizontally
            if dist < best_dist:
                best = other
                best_dist = dist
            elif dist == best_dist and best is not None:
                # tie-breaker? keep first or compare
                pass
    if best is not None:
        edges.append((best, name))

